// A callback recipe, shown alone for reading:
// x => x.fast(2)
// Next lesson puts it inside lastOf.

const drums = s("bd ~ sd ~").gain(0.25);
const hats = s("hh*8").gain(0.1);
arrange([2, drums], [4, stack(drums, hats)])

// Read-only lookup exercise:
// sound and s: aliases for a sound control
// voicing: tonal helper
// Csound-specific controls: require that engine

setcpm(140/4);
const beat = s("bd ~ sd ~").gain(0.22);
const bass = note("d2 ~ [d2 a2] ~").s("triangle").decay(0.18).sustain(0).gain(0.16);
arrange([2, beat], [4, stack(beat, bass)], [2, beat])

setcpm(120/4);
const motif = note("d4 f4 a4 e4").s("triangle").gain(0.12);
const pulse = s("bd ~ sd ~").gain(0.2);
arrange(
 [4, stack(pulse, motif)],
 [4, stack(pulse, motif.lastOf(4, x => x.rev()))],
 [2, pulse],
 [2, stack(pulse, motif)]
)
